      },
      "ResultPath": "$.languageDetection",
      "Next": "SentimentAnalysis"
    },
    "SentimentAnalysis": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sagemaker:invokeEndpoint",
      "Parameters": {
        "EndpointName": "chatbot-sentiment-abuse-endpoint",
        "Body.$": "$.languageDetection.ResultList[*]"
      },
      "ResultPath": "$.sentimentAbuse",
      "Next": "TranslationCheck"
    },
    "TranslationCheck": {
      "Type": "Choice",
      "Choices": [{
        "Variable": "$.languageDetection.ResultList[0].DominantLanguage.Code",
        "StringEquals": "en",
        "Next": "PIIRedaction"
      }],
      "Default": "Translation"
    },
    "Translation": {
      "Type": "Task",
      "Resource": "arn:aws:states:::translate:translateText",
      "Parameters": {
        "Text.$": "$.languageDetection.ResultList[*].Text",
        "SourceLanguageCode.$": "$.languageDetection.ResultList[0].DominantLanguage.Code",
        "TargetLanguageCode": "en"
      },
      "ResultPath": "$.translation",
      "Next": "PIIRedaction"
    },
    "PIIRedaction": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "redact-pii-function",
        "Payload": {
          "text.$": "$.translation.TranslatedText ?? $$.Map.Item.Value.messages[*].content",
          "piiTypes": ["EMAIL", "PHONE", "NAME", "CREDIT_CARD"]
        }
      },
      "ResultPath": "$.redacted",
      "Next": "PersistResults"
    },
    "PersistResults": {
      "Type": "Parallel",
      "Branches": [
        {
          "StartAt": "WriteToDataLake",
          "States": {
            "WriteToDataLake": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "write-ndjson-function",
                "Payload": {
                  "conversationId.$": "$$.Map.Item.Value.conversationId",
                  "originalContent.$": "$$.Map.Item.Value.messages[*].content",
                  "translatedContent.$": "$.translation.TranslatedText",
                  "language.$": "$.languageDetection.ResultList[0].DominantLanguage.Code",
                  "sentiment.$": "$.sentimentAbuse.Body.sentiment",
                  "abuseFlag.$": "$.sentimentAbuse.Body.abuse_score > 0.7",
                  "redactedContent.$": "$.redacted.Payload.redactedText"
                }
              },
              "End": true
            }
          }
        },
        {
          "StartAt": "UpdateDynamoDB",
          "States": {
            "UpdateDynamoDB": {
              "Type": "Task",
              "Resource": "arn:aws:states:::dynamodb:updateItem",
              "Parameters": {
                "TableName": "chatbot-conversations-index",
                "Key": {
                  "conversationId": {"S.$": "$$.Map.Item.Value.conversationId"}
                },
                "UpdateExpression": "SET translatedKey = :tk, language = :lang, sentiment = :sent, abuseFlag = :abuse, lastProcessed = :ts",
                "ExpressionAttributeValues": {
                  ":tk": {"S.$": "$.translation.TranslatedText"},
                  ":lang": {"S.$": "$.languageDetection.ResultList[0].DominantLanguage.Code"},
                  ":sent": {"S.$": "$.sentimentAbuse.Body.sentiment"},
